import os
matches=[]
for top in ['/inputs','/work','/tmp','/home','/opt','/root','/app','/mnt']:
    if not os.path.exists(top): continue
    for root, dirs, files in os.walk(top, topdown=True):
        dirs[:] = [d for d in dirs if d not in {'proc','sys','dev','node_modules','__pycache__'}]
        for f in files:
            if f == 'intercept-github-fetch.sh' or f.endswith(('.git','.bundle','.pack')):
                matches.append(os.path.join(root,f))
print('\n'.join(matches) if matches else 'NO MATCHES')
